window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-71cf90641a972f81"]={"versions": [{"id": "FIG-71cf90641a972f81", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM/UML-Prozessmodell) für die Adaptive Platform im Dokument <code>AUTOSAR_TR_AdaptiveMethodology</code>. Das Diagramm beschreibt die Prozesszerlegung der übergeordneten Verbundaktivität <code>Develop Adaptive Application Software</code> in spezifische Design- und Implementierungsschritte sowie deren Eingangs- und Ausgangsarbeitsergebnisse (Work Products / Deliverables).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitäten</strong>:\n<ul class=\"fig-list\"><li><code>Develop Adaptive Application Software</code>: Übergeordnete Verbundaktivität (Composite Task), geschachtelt in:\n<ul class=\"fig-list\"><li><code>Design Software Component for Adaptive Platform</code>: Vorgelagerte Entwurfsaktivität (Task).\n</li><li><code>Develop Software Components</code>: Nachgelagerte Verbundaktivität (Composite Task), wiederum hierarchisch geschachtelt («nesting») in die Einzelschritte:\n<ul class=\"fig-list\"><li><code>Generate Header Files for Service Interfaces</code>\n</li><li><code>Implement Software Component</code>\n</li><li><code>Develop Main Function</code>\n</li></ul>\n</li></ul>\n</li></ul>\n</li><li><strong>Eingangsartefakte («input»)</strong>:\n<ul class=\"fig-list\"><li><code>Service Interface Description</code>: Eingang für <code>Develop Adaptive Application Software</code> mit Multiplizität 1..*.\n</li></ul>\n</li><li><strong>Ausgangsartefakte («output»)</strong>:\n<ul class=\"fig-list\"><li><code>Software Component Description for Adaptive Platform</code>: Multiplizität 0..*.\n</li><li><code>Software Component Object Code</code>: Multiplizität 1..*.\n</li><li><code>Main Function</code>: Multiplizität 1.\n</li><li><code>Transport Layer Independent Instance ID List</code>: Multiplizität 0..*.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Bereitstellung von mindestens einer <code>Service Interface Description</code> (1..*) als externe Eingabe.\n</li><li>Durchführung von <code>Design Software Component for Adaptive Platform</code> zur formalen Schnittstellen- und Komponentenmodellierung.\n</li><li>Ausführung der Teilaktivität <code>Develop Software Components</code> mit:\n<ul class=\"fig-list\"><li>Generierung der Schnittstellen-Header-Dateien (<code>Generate Header Files for Service Interfaces</code>).\n</li><li>Implementierung der Komponentenlogik (<code>Implement Software Component</code>).\n</li><li>Entwicklung der Einstiegsfunktion (<code>Develop Main Function</code>).\n</li></ul>\n</li><li>Erzeugung der Ausgangsarbeitsergebnisse:\n<ul class=\"fig-list\"><li>Optionale Komponentenbeschreibungen (<code>Software Component Description for Adaptive Platform</code>, 0..*).\n</li><li>Mindestens eine kompilierte Objektcode-Datei (<code>Software Component Object Code</code>, 1..*).\n</li><li>Genau eine Hauptfunktion (<code>Main Function</code>, 1).\n</li><li>Optionale transportunabhängige Instanz-ID-Listen (<code>Transport Layer Independent Instance ID List</code>, 0..*).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Methodik definiert die notwendigen Schritte zur Entwicklung adaptiver Anwendungssoftware auf Basis von Service-Schnittstellen. Entwickler müssen beachten, dass die Bereitstellung der <code>Service Interface Description</code> eine zwingende Vorbedingung (Kardinalität 1..<em>) darstellt. Aus der Verbundaktivität gehen zwingend kompilierter Objektcode (1..</em>) sowie die Hauptfunktion (1) hervor, während Beschreibungsdateien und die transportunabhängige Instanz-ID-Liste optional bzw. konfigurationsabhängig anfallen.</p>"}, {"id": "FIG-703f6c7c411812c5", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM/UML-Prozessmodell) für die Adaptive Platform im Dokument <code>AUTOSAR_TR_AdaptiveMethodology</code>. Das Diagramm beschreibt die Prozesszerlegung der übergeordneten Verbundaktivität <code>Develop Adaptive Application Software</code> in spezifische Design- und Implementierungsschritte sowie deren Eingangs- und Ausgangsarbeitsergebnisse (Work Products / Deliverables).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitäten</strong>:\n<ul class=\"fig-list\"><li><code>Develop Adaptive Application Software</code>: Übergeordnete Verbundaktivität (Composite Task), gegliedert über «nesting» in:\n<ul class=\"fig-list\"><li><code>Design Software Component for Adaptive Platform</code>: Vorgelagerte Entwurfsaktivität.\n</li><li><code>Develop Software Components</code>: Nachgelagerte Verbundaktivität, weiter untergliedert über «nesting» in:\n<ul class=\"fig-list\"><li><code>Generate Header Files for Service Interfaces</code>\n</li><li><code>Implement Software Component</code>\n</li><li><code>Develop Main Function</code>\n</li></ul>\n</li></ul>\n</li></ul>\n</li><li><strong>Eingangsartefakte («input»)</strong>:\n<ul class=\"fig-list\"><li><code>Service Interface Description</code>: Multiplizität 1..*.\n</li></ul>\n</li><li><strong>Ausgangsartefakte («output»)</strong>:\n<ul class=\"fig-list\"><li><code>Software Component Description for Adaptive Platform</code>: Multiplizität 1..*.\n</li><li><code>Software Component Object Code</code>: Multiplizität 1..*.\n</li><li><code>Main Function</code>: Multiplizität 1.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eingang mindestens einer <code>Service Interface Description</code> (1..*).\n</li><li>Durchführung der Entwurfsphase (<code>Design Software Component for Adaptive Platform</code>).\n</li><li>Durchführung der Implementierungsphase (<code>Develop Software Components</code>):\n<ul class=\"fig-list\"><li>Generierung von Service-Interface-Headern (<code>Generate Header Files for Service Interfaces</code>).\n</li><li>Komponentenimplementierung (<code>Implement Software Component</code>).\n</li><li>Erstellung der Main-Funktion (<code>Develop Main Function</code>).\n</li></ul>\n</li><li>Erzeugung der Ausgabeartefakte:\n<ul class=\"fig-list\"><li>Mindestens eine <code>Software Component Description for Adaptive Platform</code> (1..*).\n</li><li>Mindestens ein <code>Software Component Object Code</code> (1..*).\n</li><li>Genau eine <code>Main Function</code> (1).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Im Methodenablauf ist die <code>Software Component Description for Adaptive Platform</code> als obligatorisches Arbeitsergebnis (Kardinalität 1..*) festgelegt. Das Erzeugen einer gültigen Manifest-/Komponentenbeschreibung ist somit für jede adaptive Anwendung verpflichtend neben Objektcode und Hauptfunktion vorgeschrieben. Ein separates Artefakt für transportunabhängige Instanz-IDs ist in dieser Phasendefinition nicht vorgesehen.</p>"}, {"id": "FIG-8086f1e75434b015", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM/UML-Prozessmodell) mit Rollenzuordnung für die Adaptive Platform im Dokument <code>AUTOSAR_TR_AdaptiveMethodology</code>. Dargestellt ist die Prozessstruktur von <code>Develop Adaptive Application Software</code> inklusive der beteiligten Entwicklerrollen (<code>Tier 2</code>), Teilaufgaben und erzeugten Artefakte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rollen</strong>:\n<ul class=\"fig-list\"><li><code>Tier 2</code>: Übergeordnete Rolle, agierend über «performs» als:\n<ul class=\"fig-list\"><li><code>+Application Software Designer</code>\n</li><li><code>+Application Software Developer</code>\n</li></ul>\n</li></ul>\n</li><li><strong>Aktivitäten</strong>:\n<ul class=\"fig-list\"><li><code>Develop Adaptive Application Software</code>: Übergeordnete Verbundaktivität, gegliedert in:\n<ul class=\"fig-list\"><li><code>Design Software Component for Adaptive Platform</code>: Ausgeführt von <code>+Application Software Designer</code>.\n</li><li><code>Develop Software Components</code>: Ausgeführt von <code>+Application Software Developer</code>, geschachtelt («nesting») in:\n<ul class=\"fig-list\"><li><code>Generate Header Files for Service Interfaces</code>\n</li><li><code>Implement Software Component</code>\n</li><li><code>Develop Main Function</code>\n</li></ul>\n</li></ul>\n</li></ul>\n</li><li><strong>Eingangsartefakte («input»)</strong>:\n<ul class=\"fig-list\"><li><code>Service Interface Description</code>: Multiplizität 1..*.\n</li></ul>\n</li><li><strong>Ausgangsartefakte («output»)</strong>:\n<ul class=\"fig-list\"><li><code>Software Component Description for Adaptive Platform</code>: Multiplizität 1..*.\n</li><li><code>Software Component Object Code</code>: Multiplizität 0..*.\n</li><li><code>Software Component Source Code</code>: Multiplizität 0..*.\n</li><li><code>Main Function</code>: Multiplizität 1.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Übergabe von mindestens einer <code>Service Interface Description</code> (1..*).\n</li><li>Rolle <code>Tier 2</code> übernimmt als <code>+Application Software Designer</code> die Ausführung von <code>Design Software Component for Adaptive Platform</code>.\n</li><li>Rolle <code>Tier 2</code> übernimmt als <code>+Application Software Developer</code> die Ausführung von <code>Develop Software Components</code>:\n<ul class=\"fig-list\"><li>Schnittstellen-Header generieren (<code>Generate Header Files for Service Interfaces</code>).\n</li><li>Softwarekomponente implementieren (<code>Implement Software Component</code>).\n</li><li>Hauptfunktion erstellen (<code>Develop Main Function</code>).\n</li></ul>\n</li><li>Bereitstellung der Ergebnisse:\n<ul class=\"fig-list\"><li>Mindestens eine formale Beschreibung (<code>Software Component Description for Adaptive Platform</code>, 1..*).\n</li><li>Quellcode der Komponente (<code>Software Component Source Code</code>, 0..*).\n</li><li>Kompilierter Objektcode (<code>Software Component Object Code</code>, 0..*).\n</li><li>Hauptfunktion (<code>Main Function</code>, 1).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation verankert eine klare Aufgabenteilung innerhalb der Tier-2-Rolle zwischen Designer (Entwurf der Komponentenbeschreibung) und Developer (Codeerstellung). Zudem ist die Generierung von Quell- und Objektcode nun mit Kardinalität 0..* modelliert, wodurch Workflows unterstützt werden, bei denen reiner Quellcode geliefert wird oder Objektcode erst in späteren Integrationsschritten entsteht; zwingend erforderlich bleiben stets die formale Beschreibung (1..*) und die Hauptfunktion (1).</p>"}, {"id": "FIG-dcc467b534f7c015", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM/UML-Prozessmodell) mit Rollenzuordnung für die Adaptive Platform im Dokument <code>AUTOSAR_TR_AdaptiveMethodology</code>. Dargestellt ist die Prozessstruktur von <code>Develop Adaptive Application Software</code> inklusive der beteiligten Entwicklerrollen (<code>Tier 2</code>), Teilaufgaben und erzeugten Artefakte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rollen</strong>:\n<ul class=\"fig-list\"><li><code>Tier 2</code>: Übergeordnete Rolle, agierend über «performs» als:\n<ul class=\"fig-list\"><li><code>+Application Software Designer</code>\n</li><li><code>+Application Software Developer</code>\n</li></ul>\n</li></ul>\n</li><li><strong>Aktivitäten</strong>:\n<ul class=\"fig-list\"><li><code>Develop Adaptive Application Software</code>: Übergeordnete Verbundaktivität, gegliedert in:\n<ul class=\"fig-list\"><li><code>Design Software Component for Adaptive Platform</code>: Ausgeführt von <code>+Application Software Designer</code>.\n</li><li><code>Develop Software Components</code>: Ausgeführt von <code>+Application Software Developer</code>, geschachtelt («nesting») in:\n<ul class=\"fig-list\"><li><code>Generate Header Files for Service Interfaces</code>\n</li><li><code>Implement Software Component</code>\n</li><li><code>Develop Main Function</code>\n</li></ul>\n</li></ul>\n</li></ul>\n</li><li><strong>Eingangsartefakte («input»)</strong>:\n<ul class=\"fig-list\"><li><code>Service Interface Description</code>: Multiplizität 1..*.\n</li></ul>\n</li><li><strong>Ausgangsartefakte («output»)</strong>:\n<ul class=\"fig-list\"><li><code>Software Component Description for Adaptive Platform</code>: Multiplizität 1..*.\n</li><li><code>Software Component Object Code</code>: Multiplizität 0..*.\n</li><li><code>Software Component Source Code</code>: Multiplizität 0..*.\n</li><li><code>Main Function</code>: Multiplizität 1.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Übergabe von mindestens einer <code>Service Interface Description</code> (1..*).\n</li><li>Rolle <code>Tier 2</code> übernimmt als <code>+Application Software Designer</code> die Ausführung von <code>Design Software Component for Adaptive Platform</code>.\n</li><li>Rolle <code>Tier 2</code> übernimmt als <code>+Application Software Developer</code> die Ausführung von <code>Develop Software Components</code>:\n<ul class=\"fig-list\"><li>Schnittstellen-Header generieren (<code>Generate Header Files for Service Interfaces</code>).\n</li><li>Softwarekomponente implementieren (<code>Implement Software Component</code>).\n</li><li>Hauptfunktion erstellen (<code>Develop Main Function</code>).\n</li></ul>\n</li><li>Bereitstellung der Ergebnisse:\n<ul class=\"fig-list\"><li>Mindestens eine formale Beschreibung (<code>Software Component Description for Adaptive Platform</code>, 1..*).\n</li><li>Quellcode der Komponente (<code>Software Component Source Code</code>, 0..*).\n</li><li>Kompilierter Objektcode (<code>Software Component Object Code</code>, 0..*).\n</li><li>Hauptfunktion (<code>Main Function</code>, 1).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation verankert eine klare Aufgabenteilung innerhalb der Tier-2-Rolle zwischen Designer (Entwurf der Komponentenbeschreibung) und Developer (Codeerstellung). Zudem ist die Generierung von Quell- und Objektcode nun mit Kardinalität 0..* modelliert, wodurch Workflows unterstützt werden, bei denen reiner Quellcode geliefert wird oder Objektcode erst in späteren Integrationsschritten entsteht; zwingend erforderlich bleiben stets die formale Beschreibung (1..*) und die Hauptfunktion (1).</p>"}, {"id": "FIG-0fc1559586e637ba", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM/UML-Prozessmodell) mit Rollenzuordnung für die Adaptive Platform im Dokument <code>AUTOSAR_TR_AdaptiveMethodology</code>. Dargestellt ist die Prozessstruktur von <code>Develop Adaptive Application Software</code> inklusive der beteiligten Entwicklerrollen (<code>Tier 2</code>), Teilaufgaben und erzeugten Artefakte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rollen</strong>:\n<ul class=\"fig-list\"><li><code>Tier 2</code>: Übergeordnete Rolle, agierend über «performs» als:\n<ul class=\"fig-list\"><li><code>+Application Software Designer</code>\n</li><li><code>+Application Software Developer</code>\n</li></ul>\n</li></ul>\n</li><li><strong>Aktivitäten</strong>:\n<ul class=\"fig-list\"><li><code>Develop Adaptive Application Software</code>: Übergeordnete Verbundaktivität, gegliedert in:\n<ul class=\"fig-list\"><li><code>Design Software Component for Adaptive Platform</code>: Ausgeführt von <code>+Application Software Designer</code>.\n</li><li><code>Develop Software Components</code>: Ausgeführt von <code>+Application Software Developer</code>, geschachtelt («nesting») in:\n<ul class=\"fig-list\"><li><code>Generate Header Files for Service Interfaces</code>\n</li><li><code>Implement Software Component</code>\n</li><li><code>Develop Main Function</code>\n</li></ul>\n</li></ul>\n</li></ul>\n</li><li><strong>Eingangsartefakte («input»)</strong>:\n<ul class=\"fig-list\"><li><code>Service Interface Description</code>: Multiplizität 1..*.\n</li></ul>\n</li><li><strong>Ausgangsartefakte («output»)</strong>:\n<ul class=\"fig-list\"><li><code>Software Component Description for Adaptive Platform</code>: Multiplizität 1..*.\n</li><li><code>Software Component Object Code</code>: Multiplizität 0..*.\n</li><li><code>Software Component Source Code</code>: Multiplizität 0..*.\n</li><li><code>Main Function</code>: Multiplizität 1.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Übergabe von mindestens einer <code>Service Interface Description</code> (1..*).\n</li><li>Rolle <code>Tier 2</code> übernimmt als <code>+Application Software Designer</code> die Ausführung von <code>Design Software Component for Adaptive Platform</code>.\n</li><li>Rolle <code>Tier 2</code> übernimmt als <code>+Application Software Developer</code> die Ausführung von <code>Develop Software Components</code>:\n<ul class=\"fig-list\"><li>Schnittstellen-Header generieren (<code>Generate Header Files for Service Interfaces</code>).\n</li><li>Softwarekomponente implementieren (<code>Implement Software Component</code>).\n</li><li>Hauptfunktion erstellen (<code>Develop Main Function</code>).\n</li></ul>\n</li><li>Bereitstellung der Ergebnisse:\n<ul class=\"fig-list\"><li>Mindestens eine formale Beschreibung (<code>Software Component Description for Adaptive Platform</code>, 1..*).\n</li><li>Quellcode der Komponente (<code>Software Component Source Code</code>, 0..*).\n</li><li>Kompilierter Objektcode (<code>Software Component Object Code</code>, 0..*).\n</li><li>Hauptfunktion (<code>Main Function</code>, 1).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation verankert eine klare Aufgabenteilung innerhalb der Tier-2-Rolle zwischen Designer (Entwurf der Komponentenbeschreibung) und Developer (Codeerstellung). Zudem ist die Generierung von Quell- und Objektcode nun mit Kardinalität 0..* modelliert, wodurch Workflows unterstützt werden, bei denen reiner Quellcode geliefert wird oder Objektcode erst in späteren Integrationsschritten entsteht; zwingend erforderlich bleiben stets die formale Beschreibung (1..*) und die Hauptfunktion (1).</p>"}], "trans": [{"from": "FIG-71cf90641a972f81", "to": "FIG-703f6c7c411812c5", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Artefakt <code>Transport Layer Independent Instance ID List</code> (Ausgang, Kardinalität 0..*) wurde vollständig entfernt.\n</li><li>Kardinalität von <code>Software Component Description for Adaptive Platform</code> am Ausgang von <code>Develop Adaptive Application Software</code> von 0..* auf 1..* geändert.\n</li></ul>"}, {"from": "FIG-703f6c7c411812c5", "to": "FIG-8086f1e75434b015", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Rolle <code>Tier 2</code> ergänzt, die über «performs»-Beziehungen mit den Rollenbezeichnungen <code>+Application Software Designer</code> (führt <code>Design Software Component for Adaptive Platform</code> aus) und <code>+Application Software Developer</code> (führt <code>Develop Software Components</code> aus) verknüpft ist.\n</li><li>Neues Artefakt <code>Software Component Source Code</code> (Kardinalität 0..*) als zusätzlicher Ausgang von <code>Develop Adaptive Application Software</code> ergänzt.\n</li><li>Kardinalität des Ausgangsartefakts <code>Software Component Object Code</code> von 1..* auf 0..* geändert.\n</li></ul>"}, {"from": "FIG-8086f1e75434b015", "to": "FIG-dcc467b534f7c015", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Das Teilaktivitäts-Symbol <code>Design Software Component for Adaptive Platform</code> und die Composite-Activity <code>Develop Software Components</code> wurden tiefer positioniert; die Verschachtelungskanten («nesting») von <code>Develop Adaptive Application Software</code> verlaufen nun abgewinkelt daran vorbei.\n</li><li>Die Rolle <code>Tier 2</code> wurde zentral zwischen die beiden Teilbereiche platziert; die Pfeile von <code>+Application Software Designer</code> und <code>+Application Software Developer</code> wurden entsprechend neu geroutet.\n</li><li>Die Textbezeichnung des Sub-Tasks <code>Generate Header Files for Service Interfaces</code> wurde im Diagramm leicht nach unten verschoben, sodass die zweite Zeile („for Service Interfaces“) am unteren Rand abgeschnitten ist.\n</li></ul>"}, {"from": "FIG-dcc467b534f7c015", "to": "FIG-0fc1559586e637ba", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0fc1559586e637ba", "to": "FIG-dcc467b534f7c015", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
